,\"settings\":[],\"elements\":[{\"id\":\"0a9feae\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"5103ef1\",\"elType\":\"widget\",\"settings\":{\"button_type\":\"info\",\"text\":\"Back to dashboard\",\"link\":{\"url\":\"https:\\/\\/example.com\\/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"align\":\"center\"},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"f207f37\",\"elType\":\"section\",\"settings\":[],\"elements\":[{\"id\":\"b4546ef\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"fbcc1a2\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"loginContainer\\\">\\r\\n    <form class=\\\"login-form\\\" method=\\\"post\\\" action=\\\"\\/wp-login.php\\\">\\r\\n        <div class=\\\"form-group\\\">\\r\\n            <label for=\\\"user_login\\\">Username<\\/label>\\r\\n            <input type=\\\"text\\\" name=\\\"log\\\" id=\\\"user_login\\\" class=\\\"form-control\\\" required>\\r\\n        <\\/div>\\r\\n\\r\\n        <div class=\\\"form-group\\\">\\r\\n            <label for=\\\"user_pass\\\">Password<\\/label>\\r\\n            <input type=\\\"password\\\" name=\\\"pwd\\\" id=\\\"user_pass\\\" class=\\\"form-control\\\" required>\\r\\n        <\\/div>\\r\\n\\r\\n        <div class=\\\"form-group\\\">\\r\\n            <label>\\r\\n                <input type=\\\"checkbox\\\" name=\\\"rememberme\\\" value=\\\"forever\\\">\\r\\n                Remember Me\\r\\n            <\\/label>\\r\\n        <\\/div>\\r\\n\\r\\n        <button type=\\\"submit\\\" name=\\\"wp-submit\\\">Log In<\\/button>\\r\\n    <\\/form>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\n\\/\\/ Check login status on page load\\r\\ndocument.addEventListener(\'DOMContentLoaded\', function() {\\r\\n    const loginContainer = document.getElementById(\'loginContainer\');\\r\\n    \\r\\n    \\/\\/ If user is logged in (check for WordPress logged-in class)\\r\\n    if (document.body.classList.contains(\'logged-in\')) {\\r\\n        loginContainer.style.display = \'none\';\\r\\n    }\\r\\n});\\r\\n\\r\\ndocument.querySelector(\'.login-form\').addEventListener(\'submit\', function(e) {\\r\\n    e.preventDefault();\\r\\n    \\r\\n    const formData = new FormData(this);\\r\\n    const loginContainer = document.getElementById(\'loginContainer\');\\r\\n    \\r\\n    fetch(\'\\/wp-login.php\', {\\r\\n        method: \'POST\',\\r\\n        body: formData\\r\\n    })\\r\\n    .then(response => {\\r\\n        if (response.ok) {\\r\\n            loginContainer.style.display = \'none\'; \\/\\/ Hide form immediately after successful login\\r\\n            window.location.href = \'\\/quality-control-check\\/\'; \\/\\/ Changed redirect URL to Quality Control Check page\\r\\n        }\\r\\n    })\\r\\n    .catch(error => {\\r\\n        console.error(\'Error:\', error);\\r\\n        this.submit();\\r\\n    });\\r\\n});\\r\\n<\\/script>\\r\\n\\r\\n<style>\\r\\n.login-form {\\r\\n    max-width: 400px;\\r\\n    margin: 0 auto;\\r\\n    padding: 20px;\\r\\n}\\r\\n\\r\\n.form-group {\\r\\n    margin-bottom: 15px;\\r\\n}\\r\\n\\r\\n.form-group label {\\r\\n    display: block;\\r\\n    margin-bottom: 5px;\\r\\n}\\r\\n\\r\\n.form-control {\\r\\n    width: 100%;\\r\\n    padding: 8px;\\r\\n    border: 1px solid #ddd;\\r\\n    border-radius: 4px;\\r\\n}\\r\\n\\r\\nbutton[type=\\\"submit\\\"] {\\r\\n    width: 100%;\\r\\n    padding: 10px;\\r\\n    background: #0073aa;\\r\\n    color: white;\\r\\n    border: none;\\r\\n    border-radius: 4px;\\r\\n    cursor: pointer;\\r\\n}\\r\\n\\r\\nbutton[type=\\\"submit\\\"]:hover {\\r\\n    background: #005177;\\r\\n}\\r\\n\\r\\ninput[type=\\\"checkbox\\\"] {\\r\\n    margin-right: 5px;\\r\\n}\\r\\n<\\/style>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}],\"isInner\":false}]'),(28322,2373,'_eael_post_view_count','197'),(35617,2373,'_elementor_page_settings